// --- Low-level readers ---

function readVarInt(bytes, offset) {
  let result = 0, shift = 0, b;
  do {
    b = bytes[offset++];
    result |= (b & 0x7f) << shift;
    shift += 7;
  } while (b & 0x80);
  return { value: (result >>> 1) ^ -(result & 1), offset }; // zigzag decode
}

function readLongVarInt(bytes, offset) {
  let result = 0n, shift = 0n, b;
  do {
    b = BigInt(bytes[offset++]);
    result |= (b & 0x7fn) << shift;
    shift += 7n;
  } while (b & 0x80n);
  const zigzag = (result >> 1n) ^ (-(result & 1n));
  return { value: zigzag, offset };
}

function readFloat(bytes, offset) {
  const buf = new ArrayBuffer(4);
  const view = new DataView(buf);
  for (let i = 0; i < 4; i++) view.setUint8(i, bytes[offset + i]);
  return { value: view.getFloat32(0, true), offset: offset + 4 };
}

function readDouble(bytes, offset) {
  const buf = new ArrayBuffer(8);
  const view = new DataView(buf);
  for (let i = 0; i < 8; i++) view.setUint8(i, bytes[offset + i]);
  return { value: view.getFloat64(0, true), offset: offset + 8 };
}

function readBytesRaw(bytes, offset, len) {
  return { value: bytes.slice(offset, offset + len), offset: offset + len };
}

function utf8Decode(bytes, offset, len) {
  let str = "";
  for (let i = 0; i < len; i++) str += String.fromCharCode(bytes[offset + i]);
  return decodeURIComponent(escape(str));
}

// --- Named type resolution (records/enums/fixed referenced by name elsewhere in the schema) ---

function resolveType(type, namedTypes) {
  if (typeof type === "string" && namedTypes[type]) return namedTypes[type];
  return type;
}

function registerNamedType(type, namedTypes) {
  if (type && type.name) {
    const fullName = type.namespace ? `${type.namespace}.${type.name}` : type.name;
    namedTypes[fullName] = type;
    namedTypes[type.name] = type;
  }
}

// --- Core recursive decoder ---

function decodeValue(type, bytes, offset, namedTypes) {
  type = resolveType(type, namedTypes);

  // Union: zigzag-varint branch index, then that branch's value
  if (Array.isArray(type)) {
    const r = readVarInt(bytes, offset);
    return decodeValue(type[r.value], bytes, r.offset, namedTypes);
  }

  const typeName = typeof type === "string" ? type : type.type;

  switch (typeName) {
    case "null":
      return { value: null, offset };
    case "boolean":
      return { value: bytes[offset] !== 0, offset: offset + 1 };
    case "int": {
      const r = readVarInt(bytes, offset);
      return { value: r.value, offset: r.offset };
    }
    case "long": {
      const r = readLongVarInt(bytes, offset);
      return { value: Number(r.value), offset: r.offset };
    }
    case "float":
      return readFloat(bytes, offset);
    case "double":
      return readDouble(bytes, offset);
    case "bytes": {
      const lenR = readVarInt(bytes, offset);
      return readBytesRaw(bytes, lenR.offset, lenR.value);
    }
    case "string": {
      const lenR = readVarInt(bytes, offset);
      const str = utf8Decode(bytes, lenR.offset, lenR.value);
      return { value: str, offset: lenR.offset + lenR.value };
    }
    case "fixed": {
      registerNamedType(type, namedTypes);
      return readBytesRaw(bytes, offset, type.size);
    }
    case "enum": {
      registerNamedType(type, namedTypes);
      const r = readVarInt(bytes, offset);
      return { value: type.symbols[r.value], offset: r.offset };
    }
    case "array": {
      let result = [];
      let curOffset = offset;
      while (true) {
        const countR = readVarInt(bytes, curOffset);
        curOffset = countR.offset;
        let count = countR.value;
        if (count === 0) break;
        if (count < 0) {
          count = -count;
          curOffset += 4; // skip block byte-size for negative-count blocks
        }
        for (let i = 0; i < count; i++) {
          const itemR = decodeValue(type.items, bytes, curOffset, namedTypes);
          result.push(itemR.value);
          curOffset = itemR.offset;
        }
      }
      return { value: result, offset: curOffset };
    }
    case "map": {
      let result = {};
      let curOffset = offset;
      while (true) {
        const countR = readVarInt(bytes, curOffset);
        curOffset = countR.offset;
        let count = countR.value;
        if (count === 0) break;
        if (count < 0) {
          count = -count;
          curOffset += 4;
        }
        for (let i = 0; i < count; i++) {
          const keyR = decodeValue("string", bytes, curOffset, namedTypes);
          curOffset = keyR.offset;
          const valR = decodeValue(type.values, bytes, curOffset, namedTypes);
          curOffset = valR.offset;
          result[keyR.value] = valR.value;
        }
      }
      return { value: result, offset: curOffset };
    }
    case "record": {
      registerNamedType(type, namedTypes);
      let record = {};
      let curOffset = offset;
      for (const field of type.fields) {
        const fieldR = decodeValue(field.type, bytes, curOffset, namedTypes);
        record[field.name] = fieldR.value;
        curOffset = fieldR.offset;
      }
      return { value: record, offset: curOffset };
    }
    default:
      throw new Error(`Unsupported Avro type: ${typeName}`);
  }
}

// --- Entry point ---

function decodeAvro(schemaJsonString, bytes) {
  const schema = JSON.parse(schemaJsonString);
  const namedTypes = {};
  const result = decodeValue(schema, bytes, 0, namedTypes);
  return result.value;
}

// --- Main stage logic ---

// input.value: raw signed-byte array from the Kafka Binary input
const signedBytes = event.metadata.avroPayload;
const schemaJsonString = event.value.schema; // schema string fetched by the Read stage

// Strip 5-byte Confluent wire-format header: [magic byte][4-byte schema ID]
const avroPayload = event.metadata.avroPayload; // stripped payload from Stage 1
const record = decodeAvro(schemaJsonString, avroPayload);

stage.setValue(record);

const signedBytes = event.value.value;
const unsignedBytes = signedBytes.map(b => b & 0xFF);

function readUInt32BE(bytes, offset) {
  return (
    (bytes[offset] << 24) |
    (bytes[offset + 1] << 16) |
    (bytes[offset + 2] << 8) |
    bytes[offset + 3]
  ) >>> 0;
}

const schemaId = readUInt32BE(unsignedBytes, 1);
const avroPayload = unsignedBytes.slice(5);

stage.setMetadata("schemaId", schemaId);
stage.setMetadata("avroPayload",avroPayload);
stage.setValue(avroPayload); // stripped payload, still a raw byte array

// --- Low-level writers ---

function writeVarInt(value, bytesArr) {
  // zigzag encode first
  let zigzag = (value << 1) ^ (value >> 31);
  zigzag = zigzag >>> 0; // treat as unsigned for the shifting below
  do {
    let b = zigzag & 0x7f;
    zigzag >>>= 7;
    if (zigzag !== 0) b |= 0x80;
    bytesArr.push(b);
  } while (zigzag !== 0);
}

function writeLongVarInt(value, bytesArr) {
  let big = BigInt(value);
  let zigzag = (big << 1n) ^ (big >> 63n);
  if (zigzag < 0n) zigzag += (1n << 64n); // safety for edge cases
  do {
    let b = Number(zigzag & 0x7fn);
    zigzag >>= 7n;
    if (zigzag !== 0n) b |= 0x80;
    bytesArr.push(b);
  } while (zigzag !== 0n);
}

function writeFloat(value, bytesArr) {
  const buf = new ArrayBuffer(4);
  const view = new DataView(buf);
  view.setFloat32(0, value, true);
  for (let i = 0; i < 4; i++) bytesArr.push(view.getUint8(i));
}

function writeDouble(value, bytesArr) {
  const buf = new ArrayBuffer(8);
  const view = new DataView(buf);
  view.setFloat64(0, value, true);
  for (let i = 0; i < 8; i++) bytesArr.push(view.getUint8(i));
}

function utf8Encode(str) {
  const encoded = unescape(encodeURIComponent(str));
  const bytes = [];
  for (let i = 0; i < encoded.length; i++) bytes.push(encoded.charCodeAt(i));
  return bytes;
}

// --- Named type resolution, same pattern as decoder ---

function resolveType(type, namedTypes) {
  if (typeof type === "string" && namedTypes[type]) return namedTypes[type];
  return type;
}

function registerNamedType(type, namedTypes) {
  if (type && type.name) {
    const fullName = type.namespace ? `${type.namespace}.${type.name}` : type.name;
    namedTypes[fullName] = type;
    namedTypes[type.name] = type;
  }
}

// --- Core recursive encoder ---

function encodeValue(type, value, bytesArr, namedTypes) {
  type = resolveType(type, namedTypes);

  // Union: find which branch matches, write its index, then its value
  if (Array.isArray(type)) {
    for (let i = 0; i < type.length; i++) {
      const branchType = resolveType(type[i], namedTypes);
      const branchName = typeof branchType === "string" ? branchType : branchType.type;
      if (
        (branchName === "null" && value === null) ||
        (branchName === "boolean" && typeof value === "boolean") ||
        ((branchName === "int" || branchName === "long") && typeof value === "number") ||
        ((branchName === "float" || branchName === "double") && typeof value === "number") ||
        (branchName === "string" && typeof value === "string") ||
        (branchName === "record" && typeof value === "object")
      ) {
        writeVarInt(i, bytesArr);
        encodeValue(branchType, value, bytesArr, namedTypes);
        return;
      }
    }
    throw new Error(`No matching union branch for value: ${JSON.stringify(value)}`);
  }

  const typeName = typeof type === "string" ? type : type.type;

  switch (typeName) {
    case "null":
      return; // no bytes written
    case "boolean":
      bytesArr.push(value ? 1 : 0);
      return;
    case "int":
      writeVarInt(value, bytesArr);
      return;
    case "long":
      writeLongVarInt(value, bytesArr);
      return;
    case "float":
      writeFloat(value, bytesArr);
      return;
    case "double":
      writeDouble(value, bytesArr);
      return;
    case "bytes": {
      writeVarInt(value.length, bytesArr);
      for (const b of value) bytesArr.push(b);
      return;
    }
    case "string": {
      const encoded = utf8Encode(value);
      writeVarInt(encoded.length, bytesArr);
      for (const b of encoded) bytesArr.push(b);
      return;
    }
    case "fixed": {
      registerNamedType(type, namedTypes);
      for (const b of value) bytesArr.push(b);
      return;
    }
    case "enum": {
      registerNamedType(type, namedTypes);
      const index = type.symbols.indexOf(value);
      if (index === -1) throw new Error(`Invalid enum symbol: ${value}`);
      writeVarInt(index, bytesArr);
      return;
    }
    case "array": {
      if (value.length > 0) {
        writeVarInt(value.length, bytesArr);
        for (const item of value) {
          encodeValue(type.items, item, bytesArr, namedTypes);
        }
      }
      writeVarInt(0, bytesArr); // terminating block of length 0
      return;
    }
    case "map": {
      const keys = Object.keys(value);
      if (keys.length > 0) {
        writeVarInt(keys.length, bytesArr);
        for (const key of keys) {
          encodeValue("string", key, bytesArr, namedTypes);
          encodeValue(type.values, value[key], bytesArr, namedTypes);
        }
      }
      writeVarInt(0, bytesArr);
      return;
    }
    case "record": {
      registerNamedType(type, namedTypes);
      for (const field of type.fields) {
        encodeValue(field.type, value[field.name], bytesArr, namedTypes);
      }
      return;
    }
    default:
      throw new Error(`Unsupported Avro type: ${typeName}`);
  }
}

// --- Entry point ---

function encodeAvro(schemaJsonString, record, schemaId) {
  const schema = JSON.parse(schemaJsonString);
  const namedTypes = {};
  const bodyBytes = [];
  encodeValue(schema, record, bodyBytes, namedTypes);

  // Confluent wire format: [magic byte = 0][4-byte schema ID][payload]
  const fullBytes = [0];
  fullBytes.push((schemaId >>> 24) & 0xff);
  fullBytes.push((schemaId >>> 16) & 0xff);
  fullBytes.push((schemaId >>> 8) & 0xff);
  fullBytes.push(schemaId & 0xff);
  fullBytes.push(...bodyBytes);

  return fullBytes;
}


const symbols = ["TEMPERATURE", "PRESSURE", "VIBRATION", "HUMIDITY", "FLOW_RATE"];
const sites = ["Plant-A", "Plant-B", "Plant-C"];
const units = { TEMPERATURE: "C", PRESSURE: "psi", VIBRATION: "mm/s", HUMIDITY: "%", FLOW_RATE: "L/min" };

function randomRecord() {
  const sensorType = symbols[Math.floor(Math.random() * symbols.length)];
  return {
    id: `${Date.now()}-${Math.random()}`,//event.id,//crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`,
    device_id: `dev-${Math.floor(1000 + Math.random() * 9000)}`,
    site: sites[Math.floor(Math.random() * sites.length)],
    sensor_type: sensorType,
    value: Math.round(Math.random() * 10000) / 100,
    unit: units[sensorType],
    quality: Math.random() < 0.75 ? 192 : 0,
    timestamp: Date.now()
  };
}

// schemaJsonString + schemaId assumed available from your Read Stage / State lookup
const schemaJsonString = event.metadata.schema;
const schemaId = event.value.value.id;
const record = randomRecord();
const encodedBytes = encodeAvro(schemaJsonString, record, schemaId);

stage.setValue(encodedBytes);
stage.setMetadata("payload",record);

const sensorReadingSchema = {
  type: "record",
  name: "SensorReading",
  namespace: "com.example.testdata",
  fields: [
    { name: "id", type: "string" },
    { name: "device_id", type: "string" },
    { name: "site", type: "string" },
    { name: "sensor_type", type: { type: "enum", name: "SensorType",
        symbols: ["TEMPERATURE", "PRESSURE", "VIBRATION", "HUMIDITY", "FLOW_RATE"] } },
    { name: "value", type: "double" },
    { name: "unit", type: "string" },
    { name: "quality", type: "int" },
    { name: "timestamp", type: "long", logicalType: "timestamp-millis" }
  ]
};

const requestBody = {
  schema: JSON.stringify(sensorReadingSchema),  // stringify handles all the escaping
  schemaType: "AVRO"
};

stage.setValue(requestBody);
stage.setMetadata("schema",requestBody.schema);
